package main

import "context"

func worker(ctx context.Context, jobs <-chan int) {
	for {
		select {
		case <-ctx.Done():
			return
		case job, ok := <-jobs:
			if !ok {
				return
			}
			handle(job)
		}
	}
}

func startWorker(parent context.Context, jobs <-chan int) context.CancelFunc {
	ctx, cancel := context.WithCancel(parent)
	go worker(ctx, jobs)
	return cancel // 调用方在请求结束、任务撤销或服务关闭时调用
}

func handle(int) {}
